package com.sports.payment_service.exception; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.LocalDateTime; @RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResourceNotFoundException.class) ResponseEntity<ApiError> nf(ResourceNotFoundException e){return b(HttpStatus.NOT_FOUND,e.getMessage());} @ExceptionHandler(BadRequestException.class) ResponseEntity<ApiError> br(BadRequestException e){return b(HttpStatus.BAD_REQUEST,e.getMessage());} @ExceptionHandler(ExternalServiceException.class) ResponseEntity<ApiError> ex(ExternalServiceException e){return b(HttpStatus.BAD_GATEWAY,e.getMessage());} private ResponseEntity<ApiError>b(HttpStatus s,String m){return ResponseEntity.status(s).body(new ApiError(s.value(),m,LocalDateTime.now()));}}